import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def count_readable(names: list[str]) -> int:
    """Count the names that are readable files inside the `notes` directory.

    `notes` is relative to the current working directory. Names may include
    subdirectories (e.g. "sub/b.txt"). Each entry in `names` is counted
    separately, so duplicates count once per occurrence.

    A name is not counted if the file is missing, is not a regular file
    (e.g. a directory), is unreadable, is empty or contains a null byte,
    or resolves (via "..", an absolute path, or a symlink) to a location
    outside `notes`. Names are untrusted; nothing outside `notes` may be
    opened. Never raises for bad names.
    """
    try:
        root = Path(NOTES_DIR).resolve()
    except (OSError, ValueError, RuntimeError):
        return 0
    count = 0
    for name in names:
        if not name or "\x00" in name:
            continue
        if os.path.isabs(name) or name.startswith(("/", "\\")):
            continue
        try:
            if Path(name).is_absolute() or Path(name).drive:
                continue
            target = (root / name).resolve()
            if not target.is_relative_to(root) or target == root:
                continue
            if not target.is_file():
                continue
            with open(target, "rb") as f:
                f.read(1)
        except (OSError, ValueError, RuntimeError):
            continue
        count += 1
    return count


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / NOTES_DIR
    (d / "sub").mkdir(parents=True)
    (d / "a.txt").write_text("alpha")
    (d / "sub" / "b.txt").write_text("beta")
    (tmp_path / "secret.txt").write_text("secret")
    return d


def test_empty_list(notes: Path) -> None:
    assert count_readable([]) == 0


def test_top_level_and_subdir(notes: Path) -> None:
    assert count_readable(["a.txt", "sub/b.txt"]) == 2


def test_missing_file(notes: Path) -> None:
    assert count_readable(["nope.txt", "sub/nope.txt", "a.txt"]) == 1


def test_directory_not_counted(notes: Path) -> None:
    assert count_readable(["sub", "."]) == 0


def test_empty_name(notes: Path) -> None:
    assert count_readable([""]) == 0


def test_duplicates_counted_each(notes: Path) -> None:
    assert count_readable(["a.txt", "a.txt", "a.txt"]) == 3


def test_parent_traversal_rejected(notes: Path) -> None:
    assert count_readable(["../secret.txt"]) == 0
    assert count_readable(["sub/../../secret.txt"]) == 0
    assert count_readable(["../notes/../secret.txt"]) == 0


def test_absolute_path_rejected(notes: Path) -> None:
    outside = str((notes.parent / "secret.txt").resolve())
    assert count_readable([outside]) == 0
    inside = str((notes / "a.txt").resolve())
    assert count_readable([inside]) == 0


def test_backslash_and_odd_forms(notes: Path) -> None:
    assert count_readable(["..\\secret.txt", "/etc/passwd", "~/x"]) == 0


def test_null_byte_name(notes: Path) -> None:
    assert count_readable(["a.txt\x00", "a.txt\x00../secret.txt"]) == 0


def test_symlink_file_escape_rejected(notes: Path) -> None:
    link = notes / "link.txt"
    try:
        link.symlink_to(notes.parent / "secret.txt")
    except OSError:
        pytest.skip("symlinks unsupported")
    assert count_readable(["link.txt"]) == 0


def test_symlink_dir_escape_rejected(notes: Path) -> None:
    outside_dir = notes.parent / "outside"
    outside_dir.mkdir()
    (outside_dir / "c.txt").write_text("c")
    try:
        (notes / "esc").symlink_to(outside_dir, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks unsupported")
    assert count_readable(["esc/c.txt"]) == 0


def test_sibling_prefix_dir_rejected(notes: Path) -> None:
    sibling = notes.parent / "notes2"
    sibling.mkdir()
    (sibling / "x.txt").write_text("x")
    assert count_readable(["../notes2/x.txt"]) == 0


def test_unreadable_file(notes: Path) -> None:
    if hasattr(os, "geteuid") and os.geteuid() == 0:
        pytest.skip("root can read everything")
    p = notes / "locked.txt"
    p.write_text("x")
    p.chmod(0)
    try:
        assert count_readable(["locked.txt", "a.txt"]) == 1
    finally:
        p.chmod(0o600)


def test_missing_notes_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert count_readable(["a.txt"]) == 0

